'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');const root=path.resolve(__dirname,'..'),R=require('../game/story-closure.js'),report={date:new Date().toISOString(),version:25,checks:[],browserVerification:'DOM/input harness; real Chrome verification is recorded separately in paper-style-browser-qa.json'};
function test(name,fn){fn();report.checks.push(name);}
function walkTo(s,id){const o=R.objects(s).find(o=>o.id===id);assert.ok(o,id+' exists');const route=R.pathfind(s,Math.floor(o.x/48),Math.floor(o.y/48));for(const p of route){assert.ok(R.walkable(s,p.x,p.y));s.x=p.x;s.y=p.y;}assert.ok(R.dist(s,o)<=90,id+' reachable');return ['exit','location','dungeon'].includes(o.type)?R.automaticTravel(s):R.interact(s,id);}
function kill(s,id){assert.ok(!s.defeated.includes(id));s.defeated.push(id);const type=Object.values(R.MAPS).flatMap(m=>m.enemies).find(e=>e[0]===id)[1];R.awardEnemy(s,type);if(type==='boss')s.flags.boss=true;}
test('new character, movement collision, diagonal pathfinding',()=>{const s=R.create('晨星');assert.equal(s.hp,100);const x=s.x;R.move(s,10,0);assert.equal(s.x,x+10);assert.equal(R.walkable(s,0,0),false);assert.equal(R.walkable(s,R.center(35),R.center(16)),false);assert.ok(R.pathfind(s,11,6).length);});
test('village, forest objects and enemy spawns reachable',()=>{for(const map of ['village','forest']){const s=R.create();s.map=map;const [x,y]=R.MAPS[map].spawn;s.x=R.center(x);s.y=R.center(y);for(const o of R.objects(s))assert.ok(R.pathfind(s,Math.floor(o.x/48),Math.floor(o.y/48)).length||R.dist(s,o)<=90,o.id);for(const e of R.enemies(s))assert.ok(R.walkable(s,e.x,e.y),e.id);}});
function completeStarter(s){let r=walkTo(s,'elder');if(r.onboardingTalk)R.finishOnboardingTalk(s,r.onboardingTalk);r=walkTo(s,'onboarding-mentor');R.finishOnboardingTalk(s,r.onboardingTalk);s.x=R.center(12);s.y=R.center(8)+35;s.facing={x:0,y:-1};R.practiceStrike(s);s.facing={x:0,y:1};R.practiceAction(s,'guard');R.practiceAction(s,'dash');walkTo(s,'lamp-hub-1');r=walkTo(s,'onboarding-mentor');assert.ok(R.finishOnboardingTalk(s,r.onboardingTalk)?.claimed);}
let story=R.create('晨星');
function clearFloor(s){const def=R.CAMPAIGN_ROOMS[s.map];assert.ok(def);if(['guardian','stone-rings'].includes(def.puzzle)){require('./game-test-mechanisms.cjs')(R,s,walkTo);}else if(def.puzzle==='cargo'){require('./game-test-cargo.cjs')(R,s,walkTo);}else if(def.puzzle==='sequence'){const order=def.note.includes('南、北、東')?[1,0,2]:def.note.includes('北、東、南')?[0,2,1]:def.note.includes('南、東、北')?[1,2,0]:[0,1,2];for(const i of order)walkTo(s,['piece-a','piece-b','piece-c'][i]);}else if(def.puzzle==='mirrors'){const target=def.note.includes('北一格')?[1,2,1]:def.note.includes('南零格')?[2,0,1]:[2,1,0];for(let i=0;i<3;i++)for(let n=0;n<target[i];n++)walkTo(s,['piece-a','piece-b','piece-c'][i]);}else for(const id of ['piece-a','piece-b','piece-c'])walkTo(s,id);walkTo(s,'forward');}
function leaveApproach(s){while(R.CAMPAIGN_ROOMS[s.map])walkTo(s,'return');}
test('complete first chapter companions, approach floors, mechanisms and chapter ending',()=>{walkTo(story,'village');completeStarter(story);walkTo(story,'ina');walkTo(story,'forest');walkTo(story,'forest');for(const id of ['wood-a','wood-b','wood-c'])walkTo(story,id);walkTo(story,'grove-entry');clearFloor(story);clearFloor(story);walkTo(story,'root-a');walkTo(story,'root-b');kill(story,'moss-guard');walkTo(story,'forest-chest');walkTo(story,'grove-exit');leaveApproach(story);walkTo(story,'river');walkTo(story,'river');walkTo(story,'bridge');walkTo(story,'lumi');walkTo(story,'tide-entry');clearFloor(story);clearFloor(story);walkTo(story,'sluice-a');walkTo(story,'sluice-b');kill(story,'river-guard');walkTo(story,'river-chest');walkTo(story,'tide-cache');walkTo(story,'tide-exit');leaveApproach(story);walkTo(story,'ruins');walkTo(story,'ruins');walkTo(story,'switch');walkTo(story,'gate');walkTo(story,'belfry-entry');clearFloor(story);clearFloor(story);for(const id of ['bell-moon','bell-star','bell-sun'])walkTo(story,id);kill(story,'bell-keeper');walkTo(story,'ruin-chest');walkTo(story,'moon-cache');walkTo(story,'belfry-exit');leaveApproach(story);walkTo(story,'castle');walkTo(story,'castle');walkTo(story,'seal');kill(story,'warden');assert.equal(walkTo(story,'beacon').chapterEnd,1);assert.equal(story.party.length,0);});
test('companions require a personal story, dungeon boss and star fragment, and completed return dialogue',()=>{for(const id of ['ina','lumi']){const s=R.create(),ina=id==='ina';s.flags.started=true;s.map=ina?'village':'river';s.x=R.center(R.MAPS[s.map].spawn[0]);s.y=R.center(R.MAPS[s.map].spawn[1]);let r=walkTo(s,id);assert.ok(r.lines);assert.equal(s.party.length,0);assert.equal(R.finishCompanionTalk(s,id),false);s.defeated.push(ina?'moss-guard':'river-guard');assert.equal(R.finishCompanionTalk(s,id),false);s.bag[ina?'forestShard':'riverShard']=1;const copy=R.validate(JSON.parse(JSON.stringify(s)));assert.equal(copy.flags[id+'Story'],true);assert.equal(copy.party.length,0);r=walkTo(copy,id);assert.equal(r.companionTalk,id);assert.equal(copy.party.length,0);assert.equal(R.finishCompanionTalk(copy,id),true);assert.equal(R.finishCompanionTalk(copy,id),false);assert.equal(copy.party.length,1);assert.equal(R.validate(JSON.parse(JSON.stringify(copy))).party.length,1);assert.ok(R.taskLedger(copy).some(t=>t.id==='companion-'+id&&t.status==='done'));}const s=R.create();s.campaign.finished=[1];assert.ok(R.advanceChapter(s,2));assert.equal(s.party.length,0);});
test('return to overworld and revisit village after story completion',()=>{walkTo(story,'ruins');assert.equal(story.map,'overworld');walkTo(story,'village');assert.equal(story.map,'village');assert.ok(walkTo(story,'elder').text);assert.equal(R.regionCount(story),5);});
test('automatic entry requires walking onto icon; arrival never bounces back',()=>{for(const p of R.worldPlaces(R.create())){let s=R.create();s.x=R.center(p.x);s.y=R.center(p.y)+35;assert.equal(R.automaticTravel(s),null);s.y=R.center(p.y)+25;const r=R.automaticTravel(s);assert.ok(r.entering);assert.equal(s.map,p.id);assert.equal(R.automaticTravel(s),null);const o=R.objects(s).find(o=>o.type==='exit');s.x=o.x;s.y=o.y;assert.ok(R.automaticTravel(s).transition);assert.equal(s.map,'overworld');assert.equal(R.automaticTravel(s),null);}});
test('all world destinations have a walkable path in an open order',()=>{for(const target of R.worldPlaces(R.create())){const s=R.create();assert.ok(R.pathfind(s,target.x,target.y).length,target.id);walkTo(s,target.id);assert.equal(s.map,target.id);}});
test('equipment upgrade changes damage, respects maximum tier and persists old saves',()=>{const s=R.create();s.gold=999;const base=R.attackPower(s),received=R.receivedDamage(s,10);assert.ok(R.upgrade(s,'weapon'));assert.equal(R.attackPower(s),base+8);assert.ok(R.upgrade(s,'armor'));assert.equal(R.receivedDamage(s,10),received-2);R.upgrade(s,'weapon');R.upgrade(s,'weapon');assert.equal(R.upgrade(s,'weapon'),false);const copy=R.validate(JSON.parse(JSON.stringify(s)));assert.deepEqual(copy.equipment,s.equipment);const old=JSON.parse(JSON.stringify(s));delete old.equipment;assert.deepEqual(R.validate(old).equipment,{weapon:0,armor:0});});
test('missing bridge materials and missing copper key never consume resources',()=>{let s=R.create();s.map='river';s.x=R.center(9);s.y=R.center(8);assert.match(R.interact(s,'bridge').text,/還需要/);assert.ok(!s.flags.bridge);s.map='ruins';s.x=R.center(14);s.flags.alarmOff=true;assert.match(R.interact(s,'gate').text,/鑰匙/);assert.ok(!s.flags.gate);});
test('inventory use, shop purchases, insufficient gold, healing and experience',()=>{let s=R.create();assert.equal(R.use(s,'potion').ok,false);s.bag.potion=3;s.bag.tonic=1;s.hp=30;assert.equal(R.use(s,'potion').ok,true);assert.equal(s.hp,75);assert.equal(s.bag.potion,2);assert.equal(R.buy(s,'potion'),true);assert.equal(s.gold,6);assert.equal(R.buy(s,'potion'),false);s.stamina=1;R.use(s,'tonic');assert.equal(s.stamina,100);R.award(s,R.xpToNext(s.level),0);assert.equal(s.level,2);assert.equal(s.hp,114);});
test('death returns to village, retains quests and items, loses 10 percent gold',()=>{const s=JSON.parse(JSON.stringify(story));s.map='castle';s.gold=23;s.hp=0;R.death(s);assert.equal(s.map,'village');assert.equal(s.gold,20);assert.equal(s.hp,s.maxHp);assert.equal(R.shards(s),3);assert.ok(s.campaign.finished.includes(1));});
test('save roundtrip, corruption rejection and collision recovery',()=>{R.placeParty(story);const copy=R.validate(JSON.parse(JSON.stringify(story)));assert.deepEqual(copy,story);for(const data of [null,{version:1},{...story,hp:NaN},{...story,hp:-1},{...story,map:'bad'},{...story,map:'__proto__'},{...story,level:1.5},{...story,bag:{}},{...story,maxHp:99999}])assert.throws(()=>R.validate(data));const bad={...story,x:0,y:0};assert.ok(R.walkable(R.validate(bad),R.validate(bad).x,R.validate(bad).y));});

function rng(seed=7){return ()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};}
test('resident enemies exist on entry and never refill during the same exploration visit',()=>{for(const map of Object.keys(R.SPAWN_RULES)){const s=R.create();s.map=map;if(map!=='overworld'){const at=R.MAPS[map].spawn;s.x=R.center(at[0]);s.y=R.center(at[1]);}const mobs=R.enemies(s);R.ensurePopulation(s,mobs,rng());assert.ok(mobs.filter(e=>e.hp>0).length>=4,map);assert.ok(mobs.every(e=>!e.spawnIn));const count=mobs.length;s.playtime+=2000;for(let n=0;n<20;n++)assert.equal(R.updateSpawns(s,mobs,rng()),null);assert.equal(mobs.length,count);}});
test('cleared wildlife remains peaceful across immediate reentry and returns only after time away',()=>{const s=R.create(),mobs=R.enemies(s);R.ensurePopulation(s,mobs,rng(19));for(const e of mobs){e.hp=0;assert.equal(R.markDefeated(s,e),true);assert.equal(R.markDefeated(s,e),false);}R.syncWildlife(s,mobs);R.updateEcology(s,mobs);const enter=()=>R.travel(s,R.objects(s).find(o=>o.id==='village')),exit=()=>R.travel(s,R.objects(s).find(o=>o.type==='exit'));enter();s.playtime+=30;exit();let next=R.enemies(s);R.ensurePopulation(s,next,rng());assert.equal(next.filter(e=>e.hp>0).length,0);enter();s.playtime+=R.ECOLOGY_AWAY+1;exit();next=R.enemies(s);R.ensurePopulation(s,next,rng());assert.ok(next.filter(e=>e.hp>0).length>=4);for(const map of ['village','castle','grove','tide','belfry']){s.map=map;assert.equal(R.updateSpawns(s,[]),null);}s.map='grove';s.defeated.push('moss-guard');assert.ok(!R.enemies(s).some(e=>e.id==='moss-guard'));});
test('resident health, territory and peaceful timing survive saves and invalid wildlife is rejected',()=>{const s=R.create(),mobs=R.enemies(s);R.ensurePopulation(s,mobs,rng());const e=mobs.find(e=>e.wild);e.hp=13;const home=[e.homeX,e.homeY];e.x+=5;assert.ok(R.walkable(s,e.x,e.y,14));R.syncWildlife(s,mobs);const copy=R.validate(JSON.parse(JSON.stringify(s))),loaded=R.enemies(copy).find(a=>a.id===e.id);assert.equal(loaded.hp,13);assert.deepEqual([loaded.homeX,loaded.homeY],home);const bad=JSON.parse(JSON.stringify(s));bad.wildlife.areas.overworld.active.push({id:'wild-overworld-bad',type:'boss',x:100,y:100,hp:99});assert.ok(R.validate(bad).wildlife.areas.overworld.active.every(e=>e.type!=='boss'));});
test('companions follow, cast elemental attacks, heal, conserve magic and recover at spring',()=>{const s=R.create();s.map='forest';s.x=R.center(8);s.y=R.center(7);assert.equal(R.recruit(s,'ina'),true);assert.equal(R.recruit(s,'ina'),false);R.recruit(s,'lumi');R.placeParty(s);s.hp=40;const mobs=R.enemies(s);mobs.forEach(e=>e.spawnIn=0);const events=R.stepParty(s,mobs,1.1);assert.ok(events.some(e=>e.kind==='damage'));assert.ok(events.some(e=>e.kind==='heal'));assert.equal(s.hp,72);assert.ok(s.party.find(p=>p.id==='lumi').mp<46);s.partyMode='hold';s.party.forEach(p=>p.cd=0);assert.equal(R.stepParty(s,mobs,.1).length,0);s.party[0].hp=0;s.map='village';s.x=R.center(7);s.y=R.center(8);R.interact(s,'spring');assert.equal(s.party[0].hp,R.PARTY.ina.maxHp);assert.equal(s.mp,R.maxMp(s));});
test('element weaknesses, weapon tradeoffs, magic supply and blocked line of sight',()=>{const s=R.create(),e={type:'treant'};assert.equal(R.elementDamage(s,e,30,'fire').damage,51);assert.equal(R.elementDamage(s,e,30,'physical').damage,22);assert.ok(R.WEAPONS.spear.range>R.WEAPONS.sword.range);assert.ok(R.WEAPONS.axe.cooldown>R.WEAPONS.sword.cooldown);s.gold=100;assert.ok(R.purchase(s,'spear'));assert.equal(R.purchase(s,'spear'),false);s.weapon='spear';assert.equal(R.attackPower(s),18);s.mp=0;s.stamina=100;s.bag.tonic=1;assert.equal(R.use(s,'tonic').ok,true);assert.equal(s.mp,25);s.map='grove';assert.equal(R.lineOfSight(s,{x:R.center(13),y:R.center(8)},{x:R.center(17),y:R.center(8)}),false);s.flags.groveDoor=true;assert.equal(R.lineOfSight(s,{x:R.center(13),y:R.center(8)},{x:R.center(17),y:R.center(8)}),true);});

