class Element{constructor(id='',tag='DIV'){this.id=id;this.tagName=tag;this.hidden=false;this.disabled=false;this.dataset={};this.style={};this.value='';this.textContent='';this.files=[];this.listeners={};this.children=[];this.classList={add(){},remove(){},toggle(){}};this.inner='';}set innerHTML(t){this.inner=t;for(const m of t.matchAll(/<([a-z]+)[^>]*\bid="([^"]+)"[^>]*>/g)){const el=new Element(m[2],m[1].toUpperCase());el.value=m[0].match(/\bvalue="([^"]*)"/)?.[1]||'';nodes.set(el.id,el);}if(t.includes('id="new-difficulty"'))nodes.get('new-difficulty').value='normal';}get innerHTML(){return this.inner;}addEventListener(n,fn){(this.listeners[n]??=[]).push(fn);}dispatch(n,e){for(const fn of this.listeners[n]||[])fn(e);if(this['on'+n])this['on'+n](e);}focus(){document.activeElement=this;}closest(sel){for(const [selector,key]of [['[data-ui-tab]','uiTab'],['[data-page-step]','pageStep'],['[data-recipe-sources]','recipeSources'],['[data-gear-preview]','gearPreview'],['[data-gear-equip]','gearEquip'],['[data-craft]','craft'],['[data-repair]','repair'],['[data-buy-gear]','buyGear'],['[data-upgrade]','upgrade']])if(sel===selector&&this.dataset[key])return this;if(sel==='[data-track-task]'&&this.dataset.trackTask)return this;if(sel==='[data-action]'&&this.dataset.action)return this;if(sel==='[data-slot-action]'&&this.dataset.slotAction)return this;if(sel==='[data-use]'&&this.dataset.use)return this;if(sel==='[data-next-chapter]'&&this.dataset.nextChapter)return this;if(sel==='[data-choice]'&&this.dataset.choice)return this;if(sel==='[data-buy]'&&this.dataset.buy)return this;if(sel.includes('input')&&['INPUT','SELECT','TEXTAREA'].includes(this.tagName))return this;return null;}querySelector(){return new Element();}querySelectorAll(){return [];}getBoundingClientRect(){return {width:1280,height:800,left:0,top:0};}setPointerCapture(){}click(){}setAttribute(name,value){(this.attrs??={})[name]=String(value);}getAttribute(name){return this.attrs?.[name]??null;} }
const nodes=new Map();const html=fs.readFileSync(path.join(root,'game/index.html'),'utf8');for(const m of html.matchAll(/<([a-z]+)[^>]*\bid="([^"]+)"[^>]*>/g)){const e=new Element(m[2],m[1].toUpperCase());e.hidden=/\bhidden\b/.test(m[0]);nodes.set(e.id,e);}const touchButtons=[...html.matchAll(/<button([^>]+)>/g)].filter(m=>/data-(dir|touch)=/.test(m[1])).map(m=>{const id=m[1].match(/id="([^"]+)"/)?.[1],el=id?nodes.get(id):new Element();for(const key of ['dir','touch']){const value=m[1].match(new RegExp('data-'+key+'="([^"]+)"'))?.[1];if(value)el.dataset[key]=value;}return el;});const docHandlers={},winHandlers={},frames=[],store=new Map();let liveState,liveRuntime,liveAudio,now=0;const document={hidden:false,activeElement:null,getElementById(id){assert.ok(nodes.has(id),'element exists: '+id);return nodes.get(id);},querySelector(){return new Element();},querySelectorAll(sel){return sel==='[data-dir],[data-touch]'?touchButtons:[];},addEventListener(n,fn){(docHandlers[n]??=[]).push(fn);},createElement(){return new Element();}};
const window={PaperRPG:{...R,validate(raw){liveState=R.validate(raw);return liveState;}},createPaperRenderer(){return {resize(){},render(state,rt){liveRuntime=rt;},toWorld(x,y){return {x,y};}};},addEventListener(n,fn){(winHandlers[n]??=[]).push(fn);},devicePixelRatio:1};
const localStorage={getItem:k=>store.get(k)||null,setItem:(k,v)=>store.set(k,v)};
const sandbox={window,document,localStorage,performance:{now:()=>now},requestAnimationFrame:fn=>frames.push(fn),setTimeout:fn=>{fn();return 0;},clearTimeout(){},URL,Blob,console,Date,Math,Promise};
vm.runInNewContext(fs.readFileSync(path.join(root,'game/audio.js'),'utf8'),sandbox,{filename:'audio.js'});
