function click(action){const target=new Element();target.dataset.action=action;for(const fn of docHandlers.click||[])fn({target});}
function uiTab(kind,id){const target=new Element();target.dataset.uiTab=kind+':'+id;for(const fn of docHandlers.click)fn({target});}
function pageStep(key,step=1){const target=new Element();target.dataset.pageKey=key;target.dataset.pageStep=String(step);for(const fn of docHandlers.click)fn({target});}
function seekText(text,max=40){if(nodes.get('modal-content').innerHTML.includes(text))return;for(let n=0;n<max;n++){const prev=nodes.get('modal-content').innerHTML.match(/data-page-key="([^"]+)" data-page-step="-1" (?!disabled)/);if(!prev)break;pageStep(prev[1],-1);}for(let n=0;n<max;n++){const h=nodes.get('modal-content').innerHTML;if(h.includes(text))return;const m=h.match(/data-page-key="([^"]+)" data-page-step="1" (?!disabled)/);assert.ok(m,'next page containing '+text);pageStep(m[1]);}assert.fail('could not find '+text);}
function slot(action,index){if(nodes.get('modal-content').innerHTML.includes('data-slot-action'))seekText('data-slot="'+index+'"');const target=new Element();target.dataset.slotAction=action;target.dataset.slot=String(index);for(const fn of docHandlers.click||[])fn({target});}
function key(key,type='keydown'){for(const fn of winHandlers[type]||[])fn({key,repeat:false,target:nodes.get('world'),preventDefault(){}});}
function advance(n=1){for(let i=0;i<n;i++){const next=frames.shift();assert.ok(next);now+=16;next(now);}}
test('actual title, new game, naming, story, pause, inventory and save menus run',()=>{assert.equal(nodes.get('continue-button').disabled,true);click('new');nodes.get('new-name').value='星野';click('begin');click('intro-next');click('intro-next');click('intro-next');advance();assert.equal(liveState.name,'星野');assert.equal(nodes.get('title-screen').hidden,true);assert.ok(store.has('paper-rpg-starwatch-v2'));key('ArrowRight');advance(20);key('ArrowRight','keyup');assert.ok(liveState.x>R.center(4));key('Escape');assert.equal(nodes.get('overlay').hidden,false);click('inventory');uiTab('inventory','items');assert.match(nodes.get('modal-content').innerHTML,/紅葉藥水/);click('save');slot('save',0);const db=JSON.parse(store.get('paper-rpg-starwatch-v2'));assert.equal(db.slots[0].state.name,'星野');assert.equal(db.slots[0].state.x,liveState.x);click('close');});
