test('dash spends stamina and modal pause halts movement',()=>{key('Shift');advance();assert.ok(liveState.stamina<100);key('ArrowRight');click('pause');const x=liveState.x;advance(40);assert.equal(liveState.x,x);key('ArrowRight','keyup');click('close');});
test('actual frame loop keeps resident populations stable and pauses ecology while menus are open',()=>{liveState.map='overworld';liveState.x=R.center(4);liveState.y=R.center(13);click('save');slot('save',1);click('confirm');click('load-game');slot('load',1);click('confirm');advance();const count=liveRuntime.mobs.length,before=liveState.playtime;click('pause');advance(600);assert.equal(liveState.playtime,before);click('close');advance(600);assert.ok(liveRuntime.mobs.some(e=>e.wild));assert.ok(liveRuntime.mobs.length<=count);});
test('actual magic keys consume MP, damage enemies, heal and protect with a guard',()=>{liveState.map='forest';liveState.x=R.center(14);liveState.y=R.center(9);liveState.partyMode='hold';R.recruit(liveState,'ina');R.recruit(liveState,'lumi');click('save');slot('save',1);click('confirm');click('load-game');slot('load',1);click('confirm');advance();const e=liveRuntime.mobs.find(a=>a.id==='slime-b'),hp=e.hp,mp=liveState.mp;key('u');advance();assert.ok(e.hp<hp);assert.ok(liveState.mp<mp-5);liveState.hp=liveState.maxHp-50;liveState.mp=R.maxMp(liveState);key('i');advance();assert.ok(liveState.hp>=liveState.maxHp-10);key('l');advance(5);assert.equal(liveRuntime.guard,true);key('l','keyup');advance(5);assert.equal(liveRuntime.guard,false);});
test('O casts thunder while previous R/F/Q/T/M shortcuts cannot trigger conflicting actions',()=>{click('close');liveState.bag.forestShard=1;liveState.mp=R.maxMp(liveState);liveRuntime.skillCd.thunder=0;liveRuntime.mobs=[{id:'lightning-key',type:'slime',x:liveState.x+40,y:liveState.y,hp:200,maxHp:200,cooldown:1,windup:0,hit:0,phase:0}];key('o');assert.ok(liveRuntime.mobs[0].hp<200);assert.ok(liveState.mp<R.maxMp(liveState));liveRuntime.mobs=[];const potion=liveState.bag.potion;for(const old of ['r','f','q','t','m'])key(old);advance(12);assert.equal(liveRuntime.charge,0);assert.equal(liveRuntime.guard,false);assert.equal(liveState.bag.potion,potion);assert.equal(nodes.get('overlay').hidden,true);});
test('actual boss defeat, dialogue, beacon and ending screen complete with chapter-appropriate equipment',()=>{liveState.gold=1000;R.purchase(liveState,'axe');R.equipGear(liveState,'axe');liveState.equipment.weapon=3;liveState.level=10;liveState.xp=0;liveState.maxHp=R.maxHealth(10);liveState.map='castle';liveState.x=R.center(16);liveState.y=R.center(7);liveState.hp=liveState.maxHp;liveState.bag.potion=99;liveState.flags.seal=true;liveState.flags.started=true;liveState.bag.forestShard=1;liveState.bag.riverShard=1;liveState.bag.ruinShard=1;click('save');slot('save',2);click('load-game');slot('load',2);click('confirm');advance();const boss=liveRuntime.mobs.find(e=>e.id==='warden');for(let n=0;n<220&&boss.hp>0;n++){liveState.x=boss.x;liveState.y=boss.y-35;liveState.facing={x:0,y:1};liveState.hp=liveState.maxHp;advance(25);key('j');advance();key('j','keyup');}assert.ok(liveState.flags.boss);assert.equal(nodes.get('dialogue').hidden,false);nodes.get('dialogue-next').onclick();nodes.get('dialogue-next').onclick();liveState.x=R.center(20);liveState.y=R.center(8);key('e');assert.ok(liveState.campaign.finished.includes(1));assert.match(nodes.get('modal-content').innerHTML,/CHAPTER 1/);assert.ok(JSON.parse(store.get('paper-rpg-starwatch-v2')).auto.state.campaign.finished.includes(1));R.equipGear(liveState,'sword');click('close');});
test('actual chapter travel and story choices work through UI buttons',()=>{click('close');const target=new Element();target.dataset.nextChapter='2';for(const fn of docHandlers.click)fn({target});assert.equal(liveState.campaign.chapter,2);assert.equal(liveState.map,'harbor');while(!nodes.get('dialogue').hidden)nodes.get('dialogue-next').onclick();liveState.map='sandcity-2';liveState.x=R.center(7);liveState.y=R.center(3);key('e');assert.match(nodes.get('modal-content').innerHTML,/暮砂午後留下的水/);const choice=new Element();choice.dataset.choice='share';choice.dataset.choiceRoom='sandcity-2';for(const fn of docHandlers.click)fn({target:choice});assert.ok(liveState.campaign.rooms['sandcity-2'].done);});
test('exploration tool interaction, inventory display and sword harvesting work through game controls',()=>{click('close');liveState.map='forest';liveState.x=R.center(7);liveState.y=R.center(4);key('e');assert.ok(liveState.exploration.tools.includes('lantern'));while(!nodes.get('dialogue').hidden)nodes.get('dialogue-next').onclick();click('inventory');uiTab('inventory','exploration');assert.match(nodes.get('modal-content').innerHTML,/螢光提燈/);assert.match(nodes.get('modal-content').innerHTML,/星紋寶藏/);click('close');liveState.x=R.center(13);liveState.y=R.center(3)-35;liveState.facing={x:0,y:1};advance(30);const before=liveState.bag.potion;key('j');key('j','keyup');assert.equal(liveState.bag.potion,before+1);assert.ok(liveState.exploration.grass.includes('forest:grass-1'));});
test('outdoor rescue unlocks journal completion and the new supply through actual menus',()=>{click('close');liveState.map='forest';liveState.x=R.center(12);liveState.y=R.center(13);const def=R.WILDERNESS_EVENTS['forest-rescue'];for(const id of def.guards){if(!liveState.defeated.includes(id))liveState.defeated.push(id);const mob=liveRuntime.mobs.find(e=>e.id===id);if(mob)mob.hp=0;}key('e');assert.ok(liveState.wilderness.events[def.id].done);while(!nodes.get('dialogue').hidden)nodes.get('dialogue-next').onclick();click('journal');uiTab('journal','tasks');seekText('受困的採藥人');assert.match(nodes.get('modal-content').innerHTML,/受困的採藥人/);assert.match(nodes.get('modal-content').innerHTML,/已完成/);click('close');liveState.map='village-shop';liveState.x=R.center(7);liveState.y=R.center(4);liveState.gold=100;key('e');uiTab('shop','supplies');seekText('採藥人的補給包');assert.match(nodes.get('modal-content').innerHTML,/採藥人的補給包/);const buy=new Element();buy.dataset.buy='herbkit';const amount=liveState.bag.herbkit;for(const fn of docHandlers.click)fn({target:buy});assert.equal(liveState.bag.herbkit,amount+1);assert.equal(liveState.gold,82);click('inventory');uiTab('inventory','items');seekText('採藥人的補給包');assert.match(nodes.get('modal-content').innerHTML,/採藥人的補給包/);click('close');});
test('the actual sword control exposes a concealed entrance instead of only giving grass loot',()=>{click('close');liveState.map='forest';liveState.x=R.center(3);liveState.y=R.center(3)+35;liveState.facing={x:0,y:-1};advance(40);assert.ok(!liveState.wilderness.discovered.includes('secret-forest'));key('j');key('j','keyup');assert.ok(liveState.wilderness.discovered.includes('secret-forest'),JSON.stringify({hp:liveState.hp,clock:liveState.daynight,map:liveState.map,x:liveState.x,y:liveState.y,attack:liveRuntime.attackCd,transition:liveRuntime.transition,overlay:nodes.get('overlay').hidden,dialogue:nodes.get('dialogue').hidden}));assert.ok(R.objects(liveState).some(o=>o.id==='secret-entry'));});
test('keyboard and touch charged attacks require the exploration ability, spend stamina and cancel safely',()=>{click('close');liveState.map='forest';liveState.x=R.center(12);liveState.y=R.center(8);liveState.party=[];liveRuntime.map='forest';liveRuntime.mobs=[];liveRuntime.attackCd=0;liveRuntime.dash=0;liveRuntime.invuln=0;for(const id of ['chargedBlade','trailStep','pulseGuard'])if(!liveState.journey.abilities.includes(id))liveState.journey.abilities.push(id);liveState.stamina=100;key('h');advance(60);assert.ok(liveRuntime.charge>=.6);key('h','keyup');assert.equal(liveRuntime.charge,0);assert.equal(liveState.stamina,82);assert.ok(liveRuntime.chargedAttack);liveRuntime.dashCd=0;const before=liveState.stamina;key('Shift');assert.equal(liveState.stamina,before-18);liveRuntime.dash=0;liveRuntime.invuln=0;liveRuntime.attackCd=0;liveRuntime.attack=0;liveState.stamina=100;const button=touchButtons.find(b=>b.dataset.touch==='charge');button.dispatch('pointerdown',{type:'pointerdown',pointerId:1,preventDefault(){}});advance(60);button.dispatch('pointercancel',{type:'pointercancel'});assert.equal(liveRuntime.charge,0);assert.equal(liveRuntime.attack,0);assert.equal(liveState.stamina,100);button.dispatch('pointerdown',{type:'pointerdown',pointerId:2,preventDefault(){}});advance(60);button.dispatch('pointerup',{type:'pointerup'});assert.equal(liveState.stamina,82);button.dispatch('lostpointercapture',{type:'lostpointercapture'});assert.equal(liveState.stamina,82);});
test('timed guarding prevents damage but still consumes armor durability and holding guard does not repeat the perfect block',()=>{click('close');liveState.map='forest';liveState.x=R.center(12);liveState.y=R.center(8);liveState.hp=liveState.maxHp;liveState.mp=0;liveState.stamina=100;liveState.gear.durability.traveler=R.GEAR.traveler.durability;const armorBefore=liveState.gear.durability.traveler;liveRuntime.guard=false;liveRuntime.invuln=0;const e={id:'guard-control',type:'guard',x:liveState.x+45,y:liveState.y,homeX:liveState.x+45,homeY:liveState.y,hp:66,maxHp:66,cooldown:0,windup:0,phase:0,hit:0,mind:{mode:'chase',lost:0},tech:{kind:'lunge',phase:'act',left:.02,dx:-1,dy:0,hit:false}};liveRuntime.mobs=[e];key('l');advance(2);assert.equal(liveState.hp,liveState.maxHp);assert.equal(liveState.gear.durability.traveler,armorBefore-1);assert.ok(liveState.mp>=8);assert.ok(liveState.journey.metrics.chapters[1].parries>=1);const parries=liveState.journey.metrics.chapters[1].parries;advance(40);liveRuntime.invuln=0;e.stagger=0;e.x=liveState.x+45;e.y=liveState.y;e.tech={kind:'lunge',phase:'act',left:.02,dx:-1,dy:0,hit:false};advance(2);assert.ok(liveState.hp<liveState.maxHp);assert.equal(liveState.gear.durability.traveler,armorBefore-2);assert.equal(liveState.journey.metrics.chapters[1].parries,parries);key('l','keyup');liveRuntime.mobs=[];});
test('quest tracking and journey review run through the actual menus',()=>{click('close');liveState.onboarding.claimed=true;const q=R.SIDEQUESTS.find(q=>!liveState.campaign.quests[q.id]?.done);liveState.campaign.quests[q.id]={accepted:true,done:false};if(!liveState.campaign.tokens.includes(q.token))liveState.campaign.tokens.push(q.token);click('journal');uiTab('journal','tasks');seekText(q.title);assert.match(nodes.get('modal-content').innerHTML,/可回報/);const button=new Element();button.dataset.trackTask=q.id;for(const fn of docHandlers.click)fn({target:button});assert.equal(nodes.get('quest-title').textContent,q.title);assert.equal(liveState.journey.tracked,q.id);click('journey');assert.match(nodes.get('modal-content').innerHTML,/已記錄的旅程/);assert.match(nodes.get('modal-content').innerHTML,/閱讀與交談/);click('export-journey');click('close');});
test('motion feedback can be disabled in settings without disabling sword damage',()=>{click('settings');uiTab('settings','effects');const setting=nodes.get('effects-setting');setting.value='off';for(const fn of docHandlers.change)fn({target:setting});assert.equal(JSON.parse(store.get('paper-rpg-settings-v2')).effects,false);click('close');liveState.map='forest';liveState.x=R.center(12);liveState.y=R.center(8);liveState.facing={x:0,y:1};liveRuntime.attackCd=0;liveRuntime.hitstop=0;liveRuntime.shake=0;const e={id:'slime-feedback',type:'slime',x:liveState.x,y:liveState.y+35,homeX:liveState.x,homeY:liveState.y+35,hp:47,maxHp:47,hit:0,windup:0,phase:0,cooldown:0};liveRuntime.mobs=[e];key('j');key('j','keyup');assert.ok(e.hp<47);assert.equal(liveRuntime.hitstop,0);assert.equal(liveRuntime.shake,0);liveRuntime.mobs=[];});
test('real movement loop enters a location without E, click, or interaction',()=>{click('close');liveState.map='overworld';const village=R.worldPlaces(liveState)[0];liveState.x=R.center(village.x);liveState.y=R.center(village.y)+38;click('save');slot('save',1);slot('save',1);if(nodes.get('modal-content').innerHTML.includes('確定'))click('confirm');click('load-game');slot('load',1);click('confirm');advance(60);key('ArrowUp');advance(10);key('ArrowUp','keyup');assert.equal(liveState.map,R.CHAPTERS[R.chapter(liveState)-1].hub);});
test('actual sword kills award reduced experience with visible feedback and never reward the same enemy twice',()=>{click('close');liveState.map='forest';liveState.level=10;liveState.xp=0;liveState.maxHp=R.maxHealth(10);liveState.hp=liveState.maxHp;liveState.x=R.center(12);liveState.y=R.center(8);liveState.facing={x:0,y:1};liveState.defeated=liveState.defeated.filter(id=>id!=='slime-b');R.applyCampaign(liveState);liveRuntime.map='forest';liveRuntime.attackCd=0;liveRuntime.transition=false;liveRuntime.dash=0;liveRuntime.charge=0;liveRuntime.mobs=[{id:'slime-b',type:'slime',x:liveState.x,y:liveState.y+35,hp:1,maxHp:R.ENEMIES.slime.hp,hit:0,windup:0,cooldown:0,phase:0}];const gold=liveState.gold;key('j');key('j','keyup');assert.equal(liveState.xp,2);assert.equal(liveState.gold-gold,R.ENEMIES.slime.gold);assert.ok(liveRuntime.fx.some(f=>f.text.includes('+2 EXP')));advance(40);key('j');key('j','keyup');assert.equal(liveState.xp,2);liveRuntime.mobs=[];});
test('three audio channels and master volume persist through real settings controls without changing saves',()=>{click('settings');uiTab('settings','sound');for(const [id,value,key] of [['music-volume-setting','0','musicVolume'],['sfx-volume-setting','45','sfxVolume'],['ambient-volume-setting','80','ambientVolume'],['volume-setting','60','volume']]){const control=nodes.get(id);control.value=value;for(const fn of docHandlers.input||[])fn({target:control});assert.equal(JSON.parse(store.get('paper-rpg-settings-v2'))[key],Number(value)/100);}const before=JSON.stringify(liveState);const muted=nodes.get('sound-setting');muted.value='off';for(const fn of docHandlers.change)fn({target:muted});assert.equal(JSON.parse(store.get('paper-rpg-settings-v2')).sound,false);assert.equal(JSON.stringify(liveState),before);muted.value='on';for(const fn of docHandlers.change)fn({target:muted});click('close');});
test('audio lifecycle handlers run during focus, hidden pages and returning to the same game',()=>{click('continue');advance();click('close');const before=liveState.map;for(const fn of winHandlers.blur||[])fn();assert.equal(liveAudio.snapshot().visible,false);assert.equal(nodes.get('overlay').hidden,false);document.hidden=true;for(const fn of docHandlers.visibilitychange||[])fn();advance(10);document.hidden=false;for(const fn of docHandlers.visibilitychange||[])fn();for(const fn of winHandlers.focus||[])fn();assert.equal(liveAudio.snapshot().visible,true);click('close');advance();assert.equal(liveState.map,before);});

function gearClick(key,value){if(['gearEquip','gearPreview'].includes(key)){const spec=R.GEAR[value],h=nodes.get('modal-content').innerHTML;if(h.includes('data-ui-tab="forge:')){uiTab('forge','craft');seekText('data-gear-equip="'+value+'"');}else{if(nodes.get('overlay').hidden||!h.includes('data-ui-tab="inventory:'))click('inventory');uiTab('inventory','equipment');uiTab('equipment',spec.slot);seekText('data-gear-equip="'+value+'"');}}if(key==='buyGear'){uiTab('shop','gear');uiTab('shopgear',R.GEAR[value].slot);seekText('data-buy-gear="'+value+'"');}if(key==='upgrade'){uiTab('shop','upgrades');seekText('data-upgrade="'+value+'"');}if(key==='craft'){uiTab('forge','craft');seekText('data-craft="'+value+'"');}if(key==='repair'){uiTab('forge','repair');seekText('data-repair="'+value+'"');}const el=new Element();el.dataset[key]=value;for(const fn of docHandlers.click)fn({target:el});}
function gearLocation(map,x,y){click('close');advance();nodes.get('dialogue').hidden=true;liveState.map=map;liveState.x=R.center(x);liveState.y=R.center(y);R.applyCampaign(liveState);Object.assign(liveRuntime,{map,mobs:[],transition:false,attackCd:0,attack:0,charge:0,guard:false,invuln:0,hitstop:0,projectiles:[],path:[],target:null,dash:0,travelCooldown:1});}
test('actual equipment menus buy armor and equip three independent slots with visible durability',()=>{Object.assign(liveState,R.create('裝備旅人'));liveState.gold=1000;gearLocation('village-shop',7,4);key('e');uiTab('shop','gear');uiTab('shopgear','body');assert.match(nodes.get('modal-content').innerHTML,/身體防具/);gearClick('buyGear','leather');assert.ok(liveState.gear.owned.includes('leather'));click('inventory');uiTab('inventory','equipment');uiTab('equipment','body');assert.match(nodes.get('modal-content').innerHTML,/身體防具/);assert.match(nodes.get('modal-content').innerHTML,/耐久/);gearClick('gearEquip','leather');assert.equal(liveState.gear.equipped.body,'leather');assert.equal(liveState.gear.equipped.weapon,'sword');assert.equal(R.receivedDamage(liveState,30),28);click('save');slot('save',2);click('confirm');click('load-game');slot('load',2);click('confirm');assert.equal(liveState.gear.equipped.body,'leather');click('close');});
test('actual hidden collection, artisan dialogue, crafting, equip buttons and journal form a complete playable loop',()=>{Object.assign(liveState,R.create('星芽旅人'));liveState.gold=1000;liveState.exploration.tools.push('lantern');liveState.exploration.gates.push('secret-forest');gearLocation('secret-forest',16,5);key('e');assert.equal(liveState.gear.materials.heartwood,2);key('e');assert.equal(liveState.gear.materials.heartwood,2);gearLocation('secret-forest',19,11);key('e');assert.equal(liveState.gear.materials.glowshard,1);gearLocation('village-forge',7,4);key('e');assert.match(nodes.get('modal-content').innerHTML,/特殊加工/);gearClick('craft','starblade');assert.ok(liveState.gear.owned.includes('starblade'));assert.equal(liveState.gear.materials.heartwood,0);assert.equal(liveState.gear.materials.glowshard,0);gearClick('gearEquip','starblade');assert.equal(liveState.gear.equipped.weapon,'starblade');assert.equal(R.attackPower(liveState),27);click('journal');uiTab('journal','tasks');seekText('加工・星芽長劍');assert.match(nodes.get('modal-content').innerHTML,/加工・星芽長劍/);assert.match(nodes.get('modal-content').innerHTML,/已完成/);click('close');});
test('empty swings, enemies behind the hero and shadow evasion leave weapon and charm durability unchanged',()=>{Object.assign(liveState,R.create('命中旅人'));liveState.gold=100;R.purchase(liveState,'ward');R.equipGear(liveState,'ward');gearLocation('forest',12,8);liveState.facing={x:0,y:1};const sword=liveState.gear.durability.sword,charm=liveState.gear.durability.ward;key('j');key('j','keyup');assert.equal(liveState.gear.durability.sword,sword);assert.equal(liveState.gear.durability.ward,charm);liveRuntime.attackCd=0;liveRuntime.mobs=[{id:'behind-slime',type:'slime',x:liveState.x,y:liveState.y-35,hp:47,maxHp:47,hit:0,windup:0,cooldown:1,phase:0}];key('j');key('j','keyup');assert.equal(liveState.gear.durability.sword,sword);liveRuntime.attackCd=0;const shadow={id:'evading-shade',type:'shade',x:liveState.x,y:liveState.y+35,hp:80,maxHp:80,cloaked:true,hit:0,windup:0,cooldown:1,phase:0};liveRuntime.mobs=[shadow];key('j');key('j','keyup');assert.equal(shadow.hp,80);assert.equal(liveState.gear.durability.sword,sword);assert.equal(liveState.gear.durability.ward,charm);liveRuntime.mobs=[];});
test('a connected swing consumes one use across several enemies, a connected charged swing consumes two, and a charged miss consumes none',()=>{Object.assign(liveState,R.create('連擊旅人'));gearLocation('forest',12,8);liveState.facing={x:0,y:1};liveState.journey.abilities.push('chargedBlade');const targets=()=>[35,45].map((d,i)=>({id:'multi-contact-'+i,type:'slime',x:liveState.x,y:liveState.y+d,hp:200,maxHp:200,cooldown:1,windup:0,phase:0,hit:0}));const before=liveState.gear.durability.sword;liveRuntime.mobs=targets();key('j');key('j','keyup');assert.ok(liveRuntime.mobs.every(e=>e.hp<200));assert.equal(liveState.gear.durability.sword,before-1);liveRuntime.mobs=[];liveRuntime.attackCd=0;liveState.stamina=100;key('h');advance(60);liveRuntime.mobs=targets();key('h','keyup');assert.ok(liveRuntime.mobs.every(e=>e.hp<200));assert.equal(liveState.gear.durability.sword,before-3);liveRuntime.mobs=[];liveRuntime.attackCd=0;liveState.stamina=100;key('h');advance(60);key('h','keyup');assert.equal(liveState.gear.durability.sword,before-3);});
test('actually cutting grass consumes one weapon use and repeated swings over the cleared patch consume none',()=>{Object.assign(liveState,R.create('草葉旅人'));gearLocation('forest',13,3);liveState.y+=35;liveState.facing={x:0,y:-1};const before=liveState.gear.durability.sword;key('j');key('j','keyup');assert.ok(liveState.exploration.grass.includes('forest:grass-1'));assert.equal(liveState.gear.durability.sword,before-1);liveRuntime.attackCd=0;key('j');key('j','keyup');assert.equal(liveState.gear.durability.sword,before-1);});
test('actual swings, enemy hits and spells consume the proper durability and broken items can be reforged through the artisan menu',()=>{Object.assign(liveState,R.create('耐久旅人'));liveState.gold=1000;R.purchase(liveState,'ward');R.equipGear(liveState,'ward');liveState.gear.durability.sword=1;liveState.gear.durability.traveler=1;liveState.gear.durability.ward=3;gearLocation('forest',12,8);liveState.facing={x:0,y:1};liveRuntime.mobs=[35,45].map((d,i)=>({id:'contact-slime-'+i,type:'slime',x:liveState.x,y:liveState.y+d,hp:47,maxHp:47,cooldown:1,windup:0,phase:0,hit:0}));key('j');key('j','keyup');assert.equal(liveState.gear.durability.sword,0);assert.equal(liveState.gear.durability.ward,2);assert.equal(R.attackPower(liveState),8);liveState.journey.abilities.push('chargedBlade');key('h');assert.equal(liveRuntime.charge,0);key('h','keyup');const e={id:'durability-guard',type:'guard',x:liveState.x+45,y:liveState.y,homeX:liveState.x+45,homeY:liveState.y,hp:66,maxHp:66,cooldown:0,windup:0,phase:0,hit:0,mind:{mode:'chase',lost:0},tech:{kind:'lunge',phase:'act',left:.02,dx:-1,dy:0,hit:false}};liveRuntime.mobs=[e];advance(12);assert.equal(liveState.gear.durability.traveler,0,JSON.stringify({heroHP:liveState.hp,map:liveState.map,rtmap:liveRuntime.map,invuln:liveRuntime.invuln,tech:e.tech,enemy:e,dialog:nodes.get('dialogue').hidden,overlay:nodes.get('overlay').hidden}));assert.equal(liveState.gear.durability.ward,1);R.recruit(liveState,'ina');liveRuntime.skillCd.fire=0;liveState.mp=R.maxMp(liveState);key('u');assert.equal(liveState.gear.durability.ward,0);assert.equal(liveState.gear.equipped.charm,'ward');gearLocation('village-forge',7,4);key('e');uiTab('forge','repair');assert.match(nodes.get('modal-content').innerHTML,/重鑄/);for(const id of ['sword','traveler','ward']){gearClick('repair',id);assert.equal(liveState.gear.durability[id],R.GEAR[id].durability);}assert.ok(!R.weaponProfile(liveState).broken);click('close');advance();assert.ok(nodes.get('gear-status').textContent.includes(R.GEAR.sword.durability+'/'+R.GEAR.sword.durability));});

test('actual later-chapter shop and artisan menus show the new quotes and charge exactly once',()=>{Object.assign(liveState,R.create('金幣旅人'));liveState.gold=1000;liveState.equipment.weapon=3;liveState.equipment.armor=3;gearLocation('harbor-shop',7,4);key('e');uiTab('shop','upgrades');assert.match(nodes.get('modal-content').innerHTML,/127 G 強化/);const gold=liveState.gold;gearClick('upgrade','weapon');assert.equal(liveState.equipment.weapon,4);assert.equal(liveState.gold,gold-127);assert.match(nodes.get('modal-content').innerHTML,/155 G 強化/);liveState.gold=100;liveState.gear.materials.mistsilver=2;liveState.gear.materials.tideglass=1;gearLocation('harbor-forge',7,4);key('e');uiTab('forge','craft');seekText('data-craft="tidepike"');assert.match(nodes.get('modal-content').innerHTML,/加工 85 G/);gearClick('craft','tidepike');assert.equal(liveState.gold,15);assert.ok(liveState.gear.owned.includes('tidepike'));liveState.gear.durability.tidepike=1;gearClick('repair','tidepike');assert.equal(liveState.gold,15);assert.equal(liveState.gear.durability.tidepike,1);uiTab('forge','repair');seekText('data-repair="tidepike"');assert.match(nodes.get('modal-content').innerHTML,/修理 36 G/);liveState.gold=36;gearClick('repair','tidepike');assert.equal(liveState.gold,0);assert.equal(liveState.gear.durability.tidepike,R.GEAR.tidepike.durability);click('close');});

// Exercise the adjacent layout through the same real input and menu handlers.
function eventKey(key,extra={},type='keydown'){let prevented=false;for(const fn of winHandlers[type]||[])fn({key,repeat:false,target:nodes.get('world'),preventDefault(){prevented=true;},...extra});return prevented;}
function assignQuick(index,id){const control=nodes.get('quick-slot-'+index);control.value=id;for(const fn of docHandlers.change)fn({target:control});}
test('ZXCV menus toggle on the same key, switch between pages and ignore auto-repeat',()=>{Object.assign(liveState,R.create('按鍵旅人'));gearLocation('forest',12,8);for(const [button,title]of [['z','旅人的行囊'],['x','旅人手札'],['c',R.MAPS.overworld.name],['v','同行的夥伴']]){assert.ok(eventKey(button));assert.equal(nodes.get('overlay').hidden,false);assert.ok(nodes.get('modal-content').innerHTML.includes(title));eventKey(button,{repeat:true});assert.equal(nodes.get('overlay').hidden,false);key(button);assert.equal(nodes.get('overlay').hidden,true);}key('z');key('x');assert.match(nodes.get('modal-content').innerHTML,/旅人手札/);key('c');assert.match(nodes.get('modal-content').innerHTML,/world-chart/);key('c');assert.equal(nodes.get('overlay').hidden,true);});
test('menu shortcuts cannot bypass save confirmations, dialogue or focused form controls',()=>{click('title-confirm');key('z');assert.match(nodes.get('modal-content').innerHTML,/在這裡暫別/);click('cancel-confirm');click('close');const field=new Element('typing','INPUT'),x=liveState.x;eventKey('z',{target:field});eventKey('d',{target:field});advance(5);assert.equal(liveState.x,x);assert.equal(nodes.get('overlay').hidden,true);nodes.get('dialogue').hidden=false;key('z');assert.equal(nodes.get('overlay').hidden,true);nodes.get('dialogue').hidden=true;});
test('UI shows UIO directly above HJKL and all four menu shortcuts without stale hints',()=>{const keys=[...html.matchAll(/<kbd>([^<]+)<\/kbd>/g)].map(m=>m[1]);assert.deepEqual(keys.slice(keys.indexOf('U'),keys.indexOf('U')+7),['U','I','O','H','J','K','L']);for(const label of ['背包 Z','手札 X','地圖 C','夥伴 V'])assert.ok(html.includes(label));click('settings');uiTab('settings','controls');pageStep('settings:controls',1);assert.match(nodes.get('modal-content').innerHTML,/U：火花術/);assert.match(nodes.get('modal-content').innerHTML,/L：按住防禦/);pageStep('settings:controls',1);assert.match(nodes.get('modal-content').innerHTML,/1／2／3：使用指定道具/);click('close');});
test('three assignable item slots persist and consume exactly the chosen item with accurate HUD counts',()=>{Object.assign(liveState,R.create('補給旅人'));gearLocation('forest',12,8);liveState.maxHp=240;liveState.hp=10;liveState.bag.potion=3;liveState.bag.highpotion=3;liveState.bag.ether=2;liveState.mp=0;key('z');uiTab('inventory','items');assert.match(nodes.get('modal-content').innerHTML,/quick-slot-0/);assignQuick(0,'potion');assignQuick(1,'highpotion');assignQuick(2,'ether');assert.deepEqual(JSON.parse(store.get('paper-rpg-settings-v2')).quickItems,['potion','highpotion','ether']);click('close');assert.ok(eventKey('1'));assert.equal(liveState.hp,55);assert.equal(liveState.bag.potion,2);assert.equal(liveState.bag.highpotion,3);assert.equal(nodes.get('quick-count-0').textContent,2);key('2');assert.equal(liveState.hp,195);assert.equal(liveState.bag.highpotion,2);assert.equal(nodes.get('quick-name-1').textContent,R.ITEMS.highpotion.name);key('3');assert.equal(liveState.mp,R.maxMp(liveState));assert.equal(liveState.bag.ether,1);assert.equal(nodes.get('quick-count-2').textContent,1);});
test('empty slots, repeated keys, full health and paused menus do not consume other supplies',()=>{liveState.hp=liveState.maxHp;const before=liveState.bag.potion;key('1');assert.equal(liveState.bag.potion,before);liveState.hp-=100;eventKey('1',{repeat:true});assert.equal(liveState.bag.potion,before);key('z');key('1');assert.equal(liveState.bag.potion,before);click('close');liveState.bag.potion=0;key('1');assert.equal(liveState.bag.highpotion,2);assert.equal(liveState.bag.potion,0);advance(40);assert.equal(nodes.get('quick-item-0').disabled,true);const button=new Element();button.dataset.action='quick-1';for(const fn of docHandlers.click)fn({target:button});assert.equal(liveState.bag.highpotion,1);});
test('physical key positions work with non-Latin key text and release held actions safely',()=>{Object.assign(liveState,R.create('實體鍵旅人'));gearLocation('forest',12,8);liveState.facing={x:0,y:1};liveRuntime.mobs=[{id:'key-contact',type:'slime',x:liveState.x,y:liveState.y+35,hp:200,maxHp:200,cooldown:1,windup:0,phase:0,hit:0}];eventKey('ㄨ',{code:'KeyJ'});assert.ok(liveRuntime.mobs[0].hp<200);eventKey('ㄨ',{code:'KeyJ'},'keyup');liveRuntime.mobs=[];eventKey('ㄠ',{code:'KeyL'});advance(12);assert.equal(liveRuntime.guard,true);eventKey('ㄠ',{code:'KeyL'},'keyup');advance(12);assert.equal(liveRuntime.guard,false);const stamina=liveState.stamina;eventKey('ㄜ',{code:'KeyK'});assert.ok(liveState.stamina<stamina);eventKey('ㄈ',{code:'KeyZ'});assert.equal(nodes.get('overlay').hidden,false);eventKey('ㄈ',{code:'KeyZ'});assert.equal(nodes.get('overlay').hidden,true);eventKey('z',{ctrlKey:true});assert.equal(nodes.get('overlay').hidden,true);});
test('item assignments reload with legacy defaults and reject unknown, prototype and malformed IDs',()=>{const run=raw=>{let observed;const isolatedNodes=new Map([...nodes].map(([id,el])=>[id,Object.assign(new Element(id,el.tagName),{hidden:el.hidden})]));const reloadWindow={...window,PaperRPG:R,addEventListener(){},PaperAudio:{...window.PaperAudio,createAudioDirector(win,prefs){observed=prefs;return createDirector(win,prefs);}}};vm.runInNewContext(fs.readFileSync(path.join(root,'game/game.js'),'utf8'),{...sandbox,window:reloadWindow,document:{...document,addEventListener(){},getElementById(id){if(!isolatedNodes.has(id))isolatedNodes.set(id,new Element(id));return isolatedNodes.get(id);},querySelectorAll(){return[];}},localStorage:{...localStorage,getItem(key){return key==='paper-rpg-settings-v2'?JSON.stringify(raw):null;}},requestAnimationFrame(){}});return [...observed.quickItems];};assert.deepEqual(run({quickItems:['highpotion','revive','herbkit']}),['highpotion','revive','herbkit']);assert.deepEqual(run({volume:.5}),['potion','tonic','ether']);assert.deepEqual(run({quickItems:['__proto__','wood',null]}),['potion','tonic','ether']);assert.deepEqual(run({quickItems:'bad'}),['potion','tonic','ether']);});


test('Space starts and advances dialogue without attacking, repeats cannot skip lines or reopen the finished conversation',()=>{Object.assign(liveState,R.create('交談旅人'));gearLocation('village',11,6);liveRuntime.attackCd=0;const durability=liveState.gear.durability.sword;assert.equal(eventKey(' ',{code:'Space'}),true);assert.equal(nodes.get('dialogue').hidden,false);assert.equal(nodes.get('dialogue-face').getAttribute('src'),'assets/paper/person-elder.svg');assert.equal(nodes.get('interact-prompt').hidden,true);assert.equal(liveRuntime.attack,0);assert.equal(liveState.gear.durability.sword,durability);const first=nodes.get('dialogue-text').textContent;eventKey(' ',{code:'Space',repeat:true});assert.equal(nodes.get('dialogue-text').textContent,first);key('j');key('j','keyup');assert.equal(liveRuntime.attack,0);key(' ','keyup');let n=0;while(!nodes.get('dialogue').hidden){assert.ok(n++<20);eventKey(' ',{code:'Space'});key(' ','keyup');}eventKey(' ',{code:'Space',repeat:true});advance(30);assert.equal(nodes.get('dialogue').hidden,true);assert.equal(liveRuntime.attack,0);assert.equal(liveState.gear.durability.sword,durability);assert.equal(liveState.onboarding.elder,true);assert.match(nodes.get('dialogue-next').textContent,/空白/);});
test('Space away from objects never damages enemies while holding J still performs repeated sword attacks',()=>{Object.assign(liveState,R.create('分鍵旅人'));gearLocation('grove',12,8);liveState.facing={x:0,y:1};assert.equal(R.nearest(liveState),undefined);const enemy={id:'space-control',type:'slime',x:liveState.x,y:liveState.y+35,hp:500,maxHp:500,cooldown:99,windup:0,phase:0,hit:0};liveRuntime.mobs=[enemy];const before=liveState.gear.durability.sword;eventKey(' ',{code:'Space'});key(' ','keyup');assert.equal(enemy.hp,500);assert.equal(liveRuntime.attack,0);assert.equal(liveState.gear.durability.sword,before);key('j');const first=enemy.hp;assert.ok(first<500);advance(60);key('j','keyup');assert.ok(enemy.hp<first);liveRuntime.mobs=[];assert.ok(html.includes('<kbd>空白</kbd>'));click('settings');uiTab('settings','controls');pageStep('settings:controls',-1);pageStep('settings:controls',-1);assert.match(nodes.get('modal-content').innerHTML,/空白鍵：交談/);pageStep('settings:controls',1);assert.match(nodes.get('modal-content').innerHTML,/J：攻擊/);assert.ok(!nodes.get('modal-content').innerHTML.includes('J／空白鍵：攻擊'));click('close');});

