test('renderer executes title, five regions, boss telegraph, effects and mobile framing',()=>{let calls=0;const ctx=new Proxy({createLinearGradient:()=>({addColorStop(){}}),createRadialGradient:()=>({addColorStop(){}})}, {get(t,k){if(k in t)return t[k];return (...args)=>{for(const v of args)if(typeof v==='number')assert.ok(Number.isFinite(v),'finite drawing coordinate');calls++;};},set(t,k,v){t[k]=v;return true;}});let width=1280,height=800;const c={getContext:()=>ctx,getBoundingClientRect:()=>({width,height,left:0,top:0})};const win={PaperRPG:R,devicePixelRatio:1};vm.runInNewContext(fs.readFileSync(path.join(root,'game/renderer.js'),'utf8'),{window:win,Image:class{constructor(){this.complete=true;this.naturalWidth=100;}},Map,Math});const painter=win.createPaperRenderer(c);painter.render(story,{},1,true);for(const map of Object.keys(R.MAPS)){const s=R.create();s.map=map;s.flags.bridge=true;s.flags.gate=true;s.flags.seal=true;s.flags.boss=true;s.flags.ending=true;s.x=R.center(12);s.y=R.center(8);const mobs=R.enemies(s);R.recruit(s,'ina');R.recruit(s,'lumi');R.placeParty(s);for(const e of mobs)e.windup=.5,e.hit=.2,e.hp-=3;painter.render(s,{mobs,attack:.2,moving:true,invuln:.2,projectiles:[{x:10,y:10}],fx:[{x:30,y:30,text:'21',life:.5}]},2,false);width=390;height=844;painter.resize();painter.render(s,{mobs},3,false);painter.minimap(s,{width:160,height:104,getContext:()=>ctx});const p=painter.toWorld(100,200);assert.ok(Number.isFinite(p.x)&&Number.isFinite(p.y));width=1280;height=800;painter.resize();}const cargo=R.create();cargo.map='tide-cargo';cargo.x=R.center(15);cargo.y=R.center(8);for(const places of [{wood:'held',medicine:'bank',food:'bank',heavy:'left'},{wood:'left',medicine:'left',food:'left',heavy:'left'},{wood:'left',medicine:'right',food:'right',heavy:'left'}]){cargo.cargoLift.places=places;R.grid(cargo);cargo.campaign.rooms['tide-cargo'].done=places.food==='right';for(const size of [[1280,800],[390,844]]){[width,height]=size;painter.resize();painter.render(cargo,{mobs:[]},4,false);}}for(const map of ['ashland-2','sanctuary-1']){const fixture=R.create();fixture.map=map;fixture.x=R.center(13);fixture.y=R.center(10);if(map==='ashland-2'){fixture.storyMechanisms.guardian={plan:[...R.GUARDIAN_SOLUTION],index:6,running:true,elapsed:.275,failed:false};}else{fixture.storyMechanisms.plate={seals:['sun','moon','star'],rings:[0,1,2],lore:true};}for(const size of [[1280,800],[390,844]]){[width,height]=size;painter.resize();painter.render(fixture,{mobs:[]},5,false);}}for(const map of ['river','secret-river','mirrormarsh','harbor','skyroad','bastion']){const fixture=R.create();fixture.map=map;fixture.x=R.center(10);fixture.y=R.center(9);fixture.campaign.rooms['tide-cargo']={done:true};for(const q of ['side-2','side-4','side-8'])fixture.campaign.quests[q]={done:true};Object.assign(fixture.worldRecovery,{tracks:true,hoist:true,delivered:true,water:true});for(const size of [[1280,800],[390,844]]){[width,height]=size;painter.resize();painter.render(fixture,{mobs:[]},6,false);}}assert.ok(calls>1000);});

test('conversation portraits match map identities while notes and chapter narration stay symbolic',()=>{
 const s=R.create('測試旅人'),before=JSON.stringify(s);
 const cases=[['village','npc','elder','村長・苔爺','elder'],['village','npc','ina','伊娜','ina'],['river','npc','lumi','露米','lumi'],['village','npc','onboarding-mentor','守望人・阿嵐','ranger'],['village-forge','gear-artisan','artisan','苔爐匠・洛木','artisan'],['village-shop','shop','merchant','旅行商人・米菈','merchant'],['village-elder','home-object','home-host','正在整理書頁的長者','elder'],['harbor','port-person','port-cargo-clerk','藥船的理貨員','merchant'],['ashland-archive','port-person','port-keeper','守著手記的抄寫人','elder'],['secret-river','wild-cave','cave-traveler','留下的便條','story']];
 for(const [map,type,id,speaker,kind]of cases){const state={...s,map},o={type,id,name:speaker};assert.equal(R.dialoguePortrait(state,speaker,o).kind,kind,speaker);}
 assert.equal(R.dialoguePortrait(s,'守著手記的抄寫人',{id:'port-archive-door',type:'dungeon'}).kind,'elder');
 assert.equal(R.dialoguePortrait(s,'遺落的星光').kind,'story');assert.equal(R.dialoguePortrait(s,'熄滅的星燈').kind,'story');assert.equal(R.dialoguePortrait(s,s.name).kind,'hero');
 assert.equal(R.dialoguePortrait(s,'伊娜').src,'assets/paper/person-ina.svg');assert.equal(JSON.stringify(s),before);
});

test('friendly actors share hero frames across village, interiors, overworld and recruited companions',()=>{
 const drawn=[],ctx=new Proxy({createLinearGradient:()=>({addColorStop(){}}),createRadialGradient:()=>({addColorStop(){}}),drawImage(im,x,y,w,h){drawn.push({src:im.src,x,y,w,h});}},{get(t,k){return k in t?t[k]:()=>{};},set(t,k,v){t[k]=v;return true;}});
 const fixtures=[['elder','npc'],['merchant','shop'],['ranger','npc'],['ina','npc'],['lumi','npc'],['side-0','campaign'],['artisan','gear-artisan'],['resident','journey-villager'],['home-host','home-object'],['cave-traveler','wild-cave'],['rescue-1','wild-rescue']].map(([id,type],i)=>({id,type,x:400+i*8,y:400,name:id,data:{}}));
 const win={PaperRPG:{...R,objects:()=>fixtures},devicePixelRatio:1};
 vm.runInNewContext(fs.readFileSync(path.join(root,'game/renderer.js'),'utf8'),{window:win,Image:class{constructor(){this.complete=true;this.naturalWidth=300;}},Map,Math});
 const painter=win.createPaperRenderer({getContext:()=>ctx,getBoundingClientRect:()=>({width:1280,height:800,left:0,top:0})});
 for(const map of ['village','village-shop','overworld']){
  const state=R.create();state.map=map;R.recruit(state,'ina');R.recruit(state,'lumi');R.placeParty(state);drawn.length=0;painter.render(state,{mobs:[]},1);
  const hero=drawn.find(d=>d.src==='assets/paper/hero.svg');assert.ok(hero);const people=drawn.filter(d=>d.src.startsWith('assets/paper/person-')&&!/-edge\.svg$|-flash\.svg$/.test(d.src));assert.equal(people.length,fixtures.length+2);
  for(const person of people){assert.equal(person.w,hero.w);assert.equal(person.h,hero.h);}
  for(const kind of ['elder','merchant','ranger','villager','artisan','traveler','ina','lumi'])assert.ok(people.some(d=>d.src==='assets/paper/person-'+kind+'.svg'),kind);
 }
 for(const kind of Object.keys(require('./build-game-characters.cjs').profiles)){
  const svg=fs.readFileSync(path.join(root,'game/assets/person-'+kind+'.svg'),'utf8');assert.ok(svg.includes('viewBox="0 0 300 400"'));assert.ok(svg.includes('m116 289-7 70-37 16h71'));assert.ok(!svg.includes('m220 163 13 83'));
 }
});

