 let autoBefore,armorBefore,usedPotion;
 test('a nearby star lamp lights, updates the revival location and autosaves without healing or repairing',()=>{Object.assign(liveState,R.create('星燈試玩'));gearLocation('grove',3,8);liveState.gold=101;liveState.hp=73;liveState.mp=11;liveState.gear.durability.sword=13;liveState.gear.durability.traveler=9;R.recruit(liveState,'ina');key('e');assert.match(nodes.get('modal-content').innerHTML,/旅程已自動儲存/);assert.equal(R.currentCheckpoint(liveState).id,'lamp-grove');assert.equal(liveState.hp,73);assert.equal(liveState.mp,11);assert.equal(liveState.gear.durability.sword,13);assert.equal(JSON.parse(store.get('paper-rpg-starwatch-v2')).auto.state.checkpoints.active[1],'lamp-grove');click('save');slot('save',0);click('confirm');click('close');advance(20);autoBefore=JSON.stringify(JSON.parse(store.get('paper-rpg-starwatch-v2')).auto);});
 test('a lethal hit opens a frozen choice screen without charging gold or overwriting the healthy autosave',()=>{liveState.hp=1;liveRuntime.invuln=0;liveRuntime.projectiles=[{x:liveState.x,y:liveState.y,vx:0,vy:0,life:2,damage:999}];armorBefore=liveState.gear.durability.traveler;usedPotion=liveState.bag.potion;advance(20);assert.equal(liveState.hp,0);assert.equal(liveState.gold,101);assert.equal(liveState.gear.durability.traveler,armorBefore-1);assert.match(nodes.get('modal-content').innerHTML,/星光尚未熄滅/);assert.match(nodes.get('modal-content').innerHTML,/11 G/);const before=liveState.playtime;advance(2000);assert.equal(liveState.playtime,before);assert.equal(JSON.stringify(JSON.parse(store.get('paper-rpg-starwatch-v2')).auto),autoBefore);key('Escape');key('z');key('1');click('save');assert.match(nodes.get('modal-content').innerHTML,/星光尚未熄滅/);assert.equal(liveState.bag.potion,usedPotion);document.hidden=true;for(const fn of docHandlers.visibilitychange||[])fn();document.hidden=false;for(const fn of docHandlers.visibilitychange||[])fn();assert.equal(JSON.stringify(JSON.parse(store.get('paper-rpg-starwatch-v2')).auto),autoBefore);});
 test('death load selection can be cancelled or escaped without dismissing the fallen state',()=>{click('death-load');assert.match(nodes.get('modal-content').innerHTML,/讀取旅程/);assert.ok(!nodes.get('modal-content').innerHTML.includes('data-action="export"'));key('Escape');assert.match(nodes.get('modal-content').innerHTML,/星光尚未熄滅/);click('death-load');slot('load',0);assert.match(nodes.get('modal-content').innerHTML,/回到這段旅程/);click('cancel-confirm');assert.match(nodes.get('modal-content').innerHTML,/讀取旅程/);click('death-menu');assert.match(nodes.get('modal-content').innerHTML,/星光尚未熄滅/);});
