function finishDialogue(){let n=0;while(!nodes.get('dialogue').hidden){assert.ok(n++<20);nodes.get('dialogue-next').onclick();}}
function visitStarter(id){const o=R.objects(liveState).find(o=>o.id===id);assert.ok(o,id);liveState.x=o.x;liveState.y=o.y;liveRuntime.path=[];liveRuntime.dash=0;liveRuntime.attackCd=0;liveRuntime.mobs=[];}
