 test('Z opens the complete character panel with resources, attack, defense, mobility, recovery and locked skills',()=>{click('close');Object.assign(liveState,R.create('能力旅人'));liveState.onboarding.claimed=true;gearLocation('village',11,10);const before=JSON.stringify(liveState);key('z');uiTab('inventory','character');uiTab('ability','overview');let content=nodes.get('modal-content').innerHTML;assert.ok(content.includes('id="character-panel"'));assert.ok(!content.includes('class="equipment-summary"'));for(const tab of ['overview','attack','defense','mobility','recovery','techniques','magic'])assert.ok(content.includes('data-ui-tab="ability:'+tab+'"'));assert.match(content,/體力 <b>100 \/ 100/);uiTab('ability','attack');assert.match(nodes.get('modal-content').innerHTML,/data-stat="attack" data-current="21"/);uiTab('ability','defense');assert.match(nodes.get('modal-content').innerHTML,/data-stat="defense" data-current="0"/);uiTab('ability','techniques');assert.match(nodes.get('modal-content').innerHTML,/尚未習得/);assert.equal(JSON.stringify(liveState),before);});
