 test('mana recovery, story-mode damage factor and the level cap display independently without regenerating the hero in menus',()=>{liveState.relics.push('moon');R.gearState(liveState);liveState.mp=0;gearClick('gearEquip','moon');uiTab('inventory','character');uiTab('ability','recovery');assert.match(nodes.get('modal-content').innerHTML,/data-stat="manaRecovery" data-current="2"/);assert.equal(liveState.mp,0);liveState.difficulty='story';liveState.level=30;liveState.xp=0;liveState.maxHp=R.maxHealth(30);uiTab('ability','defense');let content=nodes.get('modal-content').innerHTML;assert.match(content,/已達最高等級/);assert.match(content,/data-stat="damageTakenPercent" data-current="50"/);assert.match(content,/data-stat="defense" data-current="0"/);uiTab('ability','overview');content=nodes.get('modal-content').innerHTML;assert.ok(content.includes(' / 506'));assert.ok(content.includes(' / 185'));assert.equal(liveState.mp,0);click('close');});
