function assertPageStructure(){const h=nodes.get('modal-content').innerHTML;const ids=[...h.matchAll(/\bid="([^"]+)"/g)].map(m=>m[1]);assert.equal(ids.length,new Set(ids).size,'unique page IDs');const stack=[],voids=new Set(['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']);for(const m of h.matchAll(/<\/?([a-z][\w-]*)\b[^>]*>/gi)){const name=m[1].toLowerCase();if(voids.has(name)||/\/\s*>$/.test(m[0]))continue;if(m[0][1]==='/')assert.equal(stack.pop(),name,'balanced '+m[0]);else stack.push(name);}assert.equal(stack.length,0,'balanced page');}
